from fastapi import FastAPI, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()
ITEMS = []


class ItemIn(BaseModel):
    name: str = Field(..., min_length=2)
    price: float = Field(..., gt=0)
    qty: int = Field(1, ge=1)


@app.post("/items", status_code=201)
def add_item(item: ItemIn):
    for it in ITEMS:
        if it["name"] == item.name:
            raise HTTPException(status_code=409, detail="Такой товар уже есть")
    ITEMS.append({"name": item.name, "price": item.price, "qty": item.qty})
    return ITEMS[-1]


@app.get("/items")
def list_items(limit: int = 10, offset: int = 0):
    return ITEMS[offset:offset + limit]


client = TestClient(app)
for n in range(1, 6):
    client.post("/items", json={"name": f"Т{n}", "price": 1.5})
for offset in (0, 2, 4, 10):
    r = client.get("/items", params={"limit": 2, "offset": offset})
    print([i["name"] for i in r.json()])
print(client.get("/items", params={"limit": "много"}).status_code)
